LETTERS = 'abcd'

def write(key, month, qs):
    lines = [
        f'@id ca_2026_{key.split("_",1)[1]}',
        f'@title करेंट अफेयर्स {month} – मासिक मॉक टेस्ट ({len(qs)} प्रश्न, रट-लो वार्षिकांक 2026)',
        f'@duration {len(qs)}',
        '@pos 1',
        '@neg 0',
        f'@instr {len(qs)} प्रश्न, प्रत्येक 1 अंक; नकारात्मक अंकन नहीं। प्रश्न व उत्तर रट-लो करेंट अफेयर्स वार्षिकांक 2026 के {month} अध्याय से; प्रत्येक उत्तर के साथ व्याख्या दी गई है।',
        '@key ' + ''.join(a.upper() for _, _, _, a, _ in qs),
        '',
        f'# करेंट अफेयर्स {month}',
    ]
    for i, (topic, stem, opts, ans, sol) in enumerate(qs, 1):
        assert len(opts) == 4 and ans in LETTERS, (key, i)
        lines += [f'{i} {topic}', f'? {stem}'] + [f'- {o}' for o in opts] + [f'= उत्तर: ({ans}) {opts[LETTERS.index(ans)]}। {sol}', f'~ करेंट अफेयर्स {month} – {topic}']
    path = f'papers/ca_2026_{key}.txt'
    with open(path, 'w', encoding='utf8') as f:
        f.write('\n'.join(lines) + '\n')
    print(path, len(qs))

if __name__ == '__main__':
    os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
    for key, (month, qs) in MONTHS.items():
        write(key, month, qs)
